DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.accept_estimate(uuid)'::regprocedure) INTO definition; definition := replace(definition, 'COALESCE(v_e.service_type, ''hotel_dog''::public.service_type), ''confirmed'',', 'COALESCE(v_e.service_type, ''hotel_dog''::public.service_type), CASE WHEN COALESCE(v_e.service_type, ''hotel_dog''::public.service_type) IN (''hotel_dog'',''hotel_cat'') THEN ''requested''::public.booking_status ELSE ''confirmed''::public.booking_status END,'); definition := replace(definition, '  UPDATE public.estimates' || chr(10) || '     SET status', '  IF COALESCE(v_e.service_type, ''hotel_dog''::public.service_type) IN (''hotel_dog'',''hotel_cat'') THEN INSERT INTO public.hotel_booking_reviews(tenant_id,booking_id,estimate_id) VALUES(v_e.tenant_id,v_booking,v_e.id) ON CONFLICT(booking_id) DO NOTHING; END IF;' || chr(10) || '  UPDATE public.estimates' || chr(10) || '     SET status'); EXECUTE definition; END $$;